//! OpenAPI 3.1 description of the HTTP API, derived from the handlers'
//! `#[utoipa::path]` annotations — source of the SDKs.
//!
//! Each controller exposes `openapi()` (its own `#[derive(OpenApi)]` listing
//! its paths); [`spec`] merges them. The written file is
//! `docs/contracts/openapi.json`, regenerated by `task openapi` and checked
//! by `tests/openapi.rs` (snapshot + every route documented or listed as
//! pending).

use utoipa::openapi::path::{Operation, ParameterBuilder, ParameterIn};
use utoipa::openapi::security::{HttpAuthScheme, HttpBuilder, SecurityRequirement, SecurityScheme};
use utoipa::openapi::{KnownFormat, ObjectBuilder, Required, SchemaFormat, Type};
use utoipa::{Modify, OpenApi, ToSchema};

use crate::controllers;

/// Error body of every non-2xx answer: machine `error` code (frontend key
/// `err-<code>`), canonical English `description`, optional `errors`:
/// `args` (interpolation strings), `fields` (`field-invalid`: field →
/// machine token) or `violations` (`*-invalid` documents). Mirrors
/// `loco_rs::controller::ErrorDetail`.
#[derive(ToSchema)]
#[allow(dead_code)]
pub struct ErrorDetail {
    pub error: Option<String>,
    pub description: Option<String>,
    pub errors: Option<serde_json::Value>,
}

/// Security scheme names used by the `security(...)` of the paths. `org`
/// marks an org-scoped route: [`spec`] turns it into the required
/// `X-Org-Id` header parameter (generators send only one scheme of an AND
/// requirement, and the org is a selection, not a credential).
pub const BEARER: &str = "bearer";
pub const ORG: &str = "org";

struct Security;

impl Modify for Security {
    fn modify(&self, openapi: &mut utoipa::openapi::OpenApi) {
        let components = openapi.components.get_or_insert_with(Default::default);
        components.add_security_scheme(
            BEARER,
            SecurityScheme::Http(
                HttpBuilder::new()
                    .scheme(HttpAuthScheme::Bearer)
                    .bearer_format("JWT")
                    .description(Some("Rauthy (OIDC) access token."))
                    .build(),
            ),
        );
    }
}

#[derive(OpenApi)]
#[openapi(
    info(title = "PNEX API", description = "HTTP API of pnex-server."),
    servers((url = "/", description = "Same origin as the PNEX server")),
    components(schemas(ErrorDetail)),
    modifiers(&Security)
)]
struct Root;

/// The committed `docs/contracts/openapi.json` text: [`spec`] plus the
/// JSON-level rewrites utoipa's typed model cannot round-trip.
pub fn spec_json() -> String {
    let mut json = serde_json::to_value(spec()).expect("spec serializes");
    plain_optional_refs(&mut json);
    serde_json::to_string_pretty(&json).expect("spec serializes") + "\n"
}

/// Full spec of the API (version = workspace version).
pub fn spec() -> utoipa::openapi::OpenApi {
    let mut doc = Root::openapi();
    doc.info.version = env!("CARGO_PKG_VERSION").to_string();
    for part in [
        controllers::health::openapi(),
        controllers::meta::openapi(),
        controllers::mcp::openapi(),
        controllers::devices::openapi(),
        controllers::media::openapi(),
        controllers::media_ingest::openapi(),
        controllers::cameras::openapi(),
        controllers::camera_recordings::openapi(),
        controllers::stitch_jobs::openapi(),
        controllers::voice_id::openapi(),
        controllers::ontology::openapi(),
        controllers::ontology_imports::openapi(),
        controllers::cases::openapi(),
        controllers::flows::openapi(),
        controllers::functions::openapi(),
        controllers::notify::openapi(),
        controllers::dashboards::openapi(),
        controllers::dashboard::openapi(),
        controllers::viz_widgets::openapi(),
        controllers::controls::openapi(),
        controllers::memory::openapi(),
        controllers::events::openapi(),
        controllers::time_ranges::openapi(),
        controllers::thermo::openapi(),
        controllers::fluid_mixtures::openapi(),
        controllers::taxonomies::openapi(),
        controllers::extension::openapi(),
        controllers::pois::openapi(),
        controllers::annotation_layers::openapi(),
        controllers::tours::openapi(),
        controllers::public_tours::openapi(),
        controllers::system::openapi(),
        controllers::resources::openapi(),
        controllers::lab::openapi(),
        controllers::ml_models::openapi(),
        controllers::ai::openapi(),
        controllers::docs::openapi(),
        controllers::doc_comments::openapi(),
        controllers::geo::openapi(),
        controllers::orgs::openapi(),
        controllers::iam::openapi(),
        controllers::user_info::openapi(),
        controllers::oauth2::openapi(),
        controllers::secrets::openapi(),
        controllers::edge_refs::openapi(),
        controllers::edge_agents::openapi(),
        controllers::firmware_projects::openapi(),
        controllers::builds::openapi(),
        controllers::pins::openapi(),
        controllers::ota::openapi(),
        controllers::boards::openapi(),
        controllers::global_search::openapi(),
        controllers::visualization::openapi(),
        controllers::ws_ticket::openapi(),
    ] {
        doc.merge(part);
    }
    ref_paginated_items(&mut doc);
    binary_bodies(&mut doc);
    for (path, item) in doc.paths.paths.iter_mut() {
        let rate_limit = crate::services::rate_limit::rule_for(path);
        for op in [
            &mut item.get,
            &mut item.post,
            &mut item.put,
            &mut item.patch,
            &mut item.delete,
        ]
        .into_iter()
        .flatten()
        {
            auth_errors(op, rate_limit);
            org_header(op);
        }
    }
    doc
}

/// Every authenticated route can answer 401 (missing/expired token),
/// every org-scoped route 403 (caller not a member of `X-Org-Id`) and every
/// rate-limited route 429: add them where the handler annotation does not
/// list them.
fn auth_errors(op: &mut Operation, rate_limit: Option<&crate::services::rate_limit::Rule>) {
    use utoipa::openapi::{RefOr, ResponseBuilder};
    let reqs = op
        .security
        .as_ref()
        .and_then(|r| serde_json::to_value(r).ok())
        .and_then(|v| v.as_array().cloned())
        .unwrap_or_default();
    let bearer = reqs.iter().any(|r| r.get(BEARER).is_some());
    let org = reqs.iter().any(|r| r.get(ORG).is_some());
    let error = |description: &str| {
        RefOr::T(
            ResponseBuilder::new()
                .description(description)
                .content(
                    "application/json",
                    utoipa::openapi::ContentBuilder::new()
                        .schema(Some(utoipa::openapi::Ref::from_schema_name("ErrorDetail")))
                        .build(),
                )
                .build(),
        )
    };
    let responses = &mut op.responses.responses;
    if bearer && !responses.contains_key("401") {
        responses.insert(
            "401".into(),
            error("Missing, invalid or expired bearer token"),
        );
    }
    if org && !responses.contains_key("403") {
        responses.insert(
            "403".into(),
            error("`org-not-member`: the caller is not a member of the `X-Org-Id` organisation"),
        );
    }
    // The engine refuses before the handler (iam.md D291): name the
    // permission every org operation needs.
    let permission = op
        .operation_id
        .as_deref()
        .and_then(pnex_api_contract::iam::operation);
    if let (Some(pnex_api_contract::iam::Access::Org(p)), Some(RefOr::T(res))) =
        (permission, responses.get_mut("403"))
    {
        res.description = format!(
            "{} · `access-denied` (`args.permission` = `{p}`): the caller's role does not grant it",
            res.description
        );
    }
    if let Some(rule) = rate_limit.filter(|_| !responses.contains_key("429")) {
        let description = format!("`{}`: rate limit reached (`Retry-After` header)", rule.code);
        responses.insert("429".into(), error(&description));
    }
}

/// `Option<Dto>` renders as `oneOf: [{type: null}, {$ref}]`, which
/// openapi-generator (3.1 support in beta) cannot process: keep the `$ref`
/// alone, the field stays optional by not being `required`.
fn plain_optional_refs(value: &mut serde_json::Value) {
    fn walk(value: &mut serde_json::Value) {
        match value {
            serde_json::Value::Object(map) => {
                let reference = map
                    .get("oneOf")
                    .and_then(|o| o.as_array())
                    .filter(|o| o.len() == 2 && o.contains(&serde_json::json!({"type": "null"})))
                    .and_then(|o| o.iter().find(|i| i.get("$ref").is_some()).cloned());
                if let Some(reference) = reference {
                    map.remove("oneOf");
                    map.extend(reference.as_object().cloned().unwrap_or_default());
                }
                map.values_mut().for_each(walk);
            }
            serde_json::Value::Array(items) => items.iter_mut().for_each(walk),
            _ => {}
        }
    }
    walk(value);
}

/// `body = Vec<u8>` renders as an integer array: a non-JSON body (file
/// upload or download) is a binary string for the SDK generators.
fn binary_bodies(doc: &mut utoipa::openapi::OpenApi) {
    use utoipa::openapi::schema::{Schema, SchemaFormat, SchemaType};
    use utoipa::openapi::{Content, RefOr};
    fn fix<'a>(content: impl Iterator<Item = (&'a String, &'a mut Content)>) {
        for (media_type, body) in content {
            if media_type.contains("json") {
                continue;
            }
            if let Some(RefOr::T(Schema::Array(_))) = body.schema {
                body.schema = Some(RefOr::T(Schema::Object(
                    ObjectBuilder::new()
                        .schema_type(SchemaType::from(Type::String))
                        .format(Some(SchemaFormat::KnownFormat(KnownFormat::Binary)))
                        .build(),
                )));
            }
        }
    }
    for item in doc.paths.paths.values_mut() {
        for op in [
            &mut item.get,
            &mut item.post,
            &mut item.put,
            &mut item.patch,
            &mut item.delete,
        ]
        .into_iter()
        .flatten()
        {
            if let Some(body) = op.request_body.as_mut() {
                fix(body.content.iter_mut());
            }
            for response in op.responses.responses.values_mut() {
                if let RefOr::T(response) = response {
                    fix(response.content.iter_mut());
                }
            }
        }
    }
}

/// utoipa inlines the type argument of a generic schema: point the
/// `results` items of each `Paginated_<T>` back to the `T` component so the
/// SDKs get one model per DTO, not a copy per list.
fn ref_paginated_items(doc: &mut utoipa::openapi::OpenApi) {
    use utoipa::openapi::schema::{ArrayItems, Schema};
    use utoipa::openapi::{Ref, RefOr};
    let Some(components) = doc.components.as_mut() else {
        return;
    };
    let names: Vec<String> = components.schemas.keys().cloned().collect();
    for (name, schema) in components.schemas.iter_mut() {
        let Some(item) = name.strip_prefix("Paginated_") else {
            continue;
        };
        if !names.iter().any(|n| n == item) {
            continue;
        }
        if let RefOr::T(Schema::Object(obj)) = schema {
            if let Some(RefOr::T(Schema::Array(results))) = obj.properties.get_mut("results") {
                results.items =
                    ArrayItems::RefOrSchema(Box::new(RefOr::Ref(Ref::from_schema_name(item))));
            }
        }
    }
}

/// Replaces the `org` security marker of an operation by the `X-Org-Id`
/// header parameter.
fn org_header(op: &mut Operation) {
    let scoped = op.security.as_ref().is_some_and(|reqs| {
        serde_json::to_value(reqs)
            .ok()
            .and_then(|v| v.as_array().cloned())
            .is_some_and(|reqs| reqs.iter().any(|r| r.get(ORG).is_some()))
    });
    if scoped {
        // shortcut: org-scoped routes are all bearer-authenticated, so the
        // requirement is rebuilt rather than edited (utoipa keeps it private).
        op.security = Some(vec![SecurityRequirement::new(BEARER, Vec::<String>::new())]);
        op.parameters.get_or_insert_with(Vec::new).insert(
            0,
            ParameterBuilder::new()
                .name("X-Org-Id")
                .parameter_in(ParameterIn::Header)
                .required(Required::True)
                .description(Some(
                    "Id of the selected organisation; the caller must be a member.",
                ))
                .schema(Some(
                    ObjectBuilder::new()
                        .schema_type(Type::Integer)
                        .format(Some(SchemaFormat::KnownFormat(KnownFormat::Int64))),
                ))
                .build(),
        );
    }
}
